import{_ as a,o as r,c as t,a2 as p}from"./chunks/framework.CqGPl1zp.js";const s="/newx-doc/assets/%E7%94%B3%E8%AF%B7%E5%88%86%E4%BD%A3%E6%8F%90%E7%8E%B0.BfC2MI37.png",o="/newx-doc/assets/%E9%80%9A%E8%BF%87%E5%88%86%E4%BD%A3%E6%8F%90%E7%8E%B0.CQ93FzWb.png",n="/newx-doc/assets/%E7%A1%AE%E8%AE%A4%E6%94%B6%E6%AC%BE.y45NxoKg.jpg",u=JSON.parse('{"title":"微信转账接入","description":"","frontmatter":{},"headers":[],"relativePath":"pay/wx-transfer-demo.md","filePath":"pay/wx-transfer-demo.md","lastUpdated":null}'),i={name:"pay/wx-transfer-demo.md"};function c(d,e,h,l,m,_){return r(),t("div",null,[...e[0]||(e[0]=[p('<h1 id="微信转账接入" tabindex="-1">微信转账接入 <a class="header-anchor" href="#微信转账接入" aria-label="Permalink to &quot;微信转账接入&quot;">​</a></h1><p>前置阅读：</p><p>① 阅读 <a href="./build">《支付功能开启》</a> 和 <a href="./alipay-transfer-demo">《支付宝转账接入》</a> 文档，一定要先跑通支付宝转账流程！！！不跑通支付宝，微信转账更跑不通。</p><p>② 阅读 <a href="./../mall/trade-brokerage">《商城手册 —— 【交易】分销返佣》</a> 文档，整体流程跑下，因为使用它作为微信转账的示例。</p><p>③ 阅读 <a href="https://pay.weixin.qq.com/doc/v3/merchant/4012711988" target="_blank" rel="noreferrer">微信商家转账</a> 的文档，特别是 <a href="https://pay.weixin.qq.com/doc/v3/merchant/4012716434" target="_blank" rel="noreferrer">《微信转账 —— 发起转账》</a> 和 <a href="https://pay.weixin.qq.com/doc/v3/merchant/4012716430" target="_blank" rel="noreferrer">《微信转账 —— JSAPI 调起用户确认收款》</a> 文档，这非常重要。相比支付宝转账来说，微信转账多了一个步骤，需要用户确认收款。</p><p>ps：没错，微信转账真的会复杂一些，需要前置阅读比较多的东西，才能跑通！！！我也开发了好几天，一度想放弃，但是还是坚持下来了！！！简直是太不容易了！！！</p><p>本小节，我们以商城的“分销提现”功能，大体讲解微信转账的接入流程，主要只会讲和支付宝转账不同的地方。</p><p>这里，使用微信小程序作为演示，其实微信公众号也是类似的。</p><h2 id="_1-【用户】申请商城分佣提现" tabindex="-1">1.【用户】申请商城分佣提现 <a class="header-anchor" href="#_1-【用户】申请商城分佣提现" aria-label="Permalink to &quot;1.【用户】申请商城分佣提现&quot;">​</a></h2><p>在商城 uniapp 微信小程序中，申请分佣提现，如下图所示：</p><p><img src="'+s+'" alt="申请分佣提现"></p><p>注意，需要选择“微信零钱”提现方式，并且最小金额是 0.3 元。</p><p>ps：这一部，不涉及到 PayTransferAPI 的调用，只是商城的 <code>trade_brokerage_withdraw</code> 表的插入操作。</p><h3 id="_2-【管理员】通过商城分佣提现" tabindex="-1">2.【管理员】通过商城分佣提现 <a class="header-anchor" href="#_2-【管理员】通过商城分佣提现" aria-label="Permalink to &quot;2.【管理员】通过商城分佣提现&quot;">​</a></h3><p>在商城后台，点击该分佣提现的【通过】按钮，如下图所示：</p><p><img src="'+o+'" alt="通过分佣提现"></p><p>此时，商城后端会调用 PayTransferAPI 的 <code>createTransfer</code> 方法，创建微信转账订单。它的内部，实际调用的是 <a href="https://pay.weixin.qq.com/doc/v3/merchant/4012716434" target="_blank" rel="noreferrer">《微信转账 —— 发起转账》</a> 。</p><p>具体的实现，可见 AppBrokerageWithdrawController 的 <code>#createBrokerageWithdraw(...)</code> 方法对应的 HTTP 接口。</p><p>补充说明：</p><p>① 微信转账 API，需要去 <a href="https://pay.weixin.qq.com/index.php/extend/mch_sec_ip" target="_blank" rel="noreferrer">https://pay.weixin.qq.com/index.php/extend/mch_sec_ip</a> 配置 IP 白名单。</p><p>② 微信转账回调接口，即 <code>application.yaml</code> 配置文件中的 <code>yudao.pay.transfer-notify-url</code> 配置项，必须是 https 协议，否则会报错。</p><h3 id="_3-【用户】确认收款" tabindex="-1">3.【用户】确认收款 <a class="header-anchor" href="#_3-【用户】确认收款" aria-label="Permalink to &quot;3.【用户】确认收款&quot;">​</a></h3><p>在商城 uniapp 微信小程序中，点击该分佣提现的【确认收款】按钮，如下图所示：</p><p><img src="'+n+'" alt="确认收款"></p><p>补充说明：</p><p>① 这里必须使用微信开发者工具的真机模拟，因为微信电脑模拟器，无法调起确认收款流程。</p><p>② 如果你使用的是商城 <code>yudao-mall-uniapp</code> 项目，需要打开 <code>sheep/libs/sdk-h5-weixin.js</code> 里的 <code>requestMerchantTransfer</code> JSAPI 权限注释：</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;requestMerchantTransfer&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// TODO @使用者：如果需要微信商家转账功能，请打开该注释；</span></span></code></pre></div><p>默认注释掉的原因是：部分公众号可能没有微信商家转账相关权限，直接放到 <code>jsApiList</code> 里会导致微信 JSSDK 初始化失败。</p><p>此时，商城 uniapp 会调用微信小程序提供的 requestMerchantTransfer 方法，确认收款。它的内部，实现调用的是 <a href="https://pay.weixin.qq.com/doc/v3/merchant/4012716430" target="_blank" rel="noreferrer">《微信转账 —— JSAPI 调起用户确认收款》</a> 。</p><p>具体的实现，可见商城 uniapp 项目的 <code>pages/commission/wallet.vue</code> 界面的 <code>#onRequestMerchantTransfer(...)</code> 方法。</p>',31)])])}const k=a(i,[["render",c]]);export{u as __pageData,k as default};
